window.DECKS = window.DECKS || [];
window.DECKS.push({"slug":"tht","name":"THT","folder":"THT","questions":[
{"id":"tht-01","p":10,"stem":"Wanita 42 tahun pendengaran telinga KIRI menurun perlahan dan makin berat. Telinga kanan normal; telinga kiri banyak serumen keras. Garpu tala: tuli konduktif telinga kiri. Hasil yang mungkin didapat adalah…","opts":["Rinne (+) kedua telinga, Weber tidak lateralisasi, Schwabach sama dengan pemeriksa","Rinne kiri (+) kanan (–), Weber lateralisasi ke kanan, Schwabach kanan memanjang","Rinne kiri (–) kanan (+), Weber lateralisasi ke kiri, Schwabach kiri memanjang","Rinne (+) kedua telinga, Weber lateralisasi ke kiri, Schwabach kanan memendek","Rinne (+) kedua telinga, Weber lateralisasi ke kanan, Schwabach kiri memendek"],"ans":2,"why":"Tuli konduktif pada telinga yang sakit: Rinne (–) (BC > AC), Weber lateralisasi KE telinga yang sakit, Schwabach memanjang. Pada tuli sensorineural: Rinne (+), Weber ke telinga sehat, Schwabach memendek.","ref":[7,8,9],"tags":["Tes garpu tala"],"skdi":"4A","src":"slide","cards":[{"q":"Tuli konduktif: Rinne?","a":"Negatif"},{"q":"Tuli konduktif: Weber lateralisasi ke…?","a":"Telinga yang sakit"},{"q":"Tuli sensorineural: Weber lateralisasi ke…?","a":"Telinga yang sehat"},{"q":"Schwabach memanjang berarti tuli…?","a":"Konduktif"}]},
{"id":"tht-02","p":10,"stem":"Wanita 23 tahun tidak bisa mendengar setelah konser band kemarin, menonton dekat speaker. Tanpa nyeri atau sekret. Audiometri: AC dan BC > 25 dB dan berhimpit. Jenis tulinya adalah…","opts":["Tuli campuran","Tuli sensorineural","Tuli konduktif","Tuli reversibel","Tuli hantaran"],"ans":1,"why":"AC dan BC sama-sama turun (> 25 dB) dan BERHIMPIT (tanpa air-bone gap) berarti tuli sensorineural, di sini akibat trauma akustik. Konduktif: BC normal, AC turun (ada gap). Campuran: keduanya turun dengan gap.","ref":[8,9],"tags":["Audiometri"],"skdi":"4A","src":"slide","cards":[{"q":"Audiometri tuli sensorineural?","a":"AC & BC turun, berhimpit (tanpa gap)"},{"q":"Audiometri tuli konduktif?","a":"BC normal, AC turun (air-bone gap)"}]},
{"id":"tht-03","p":10,"stem":"Laki-laki 28 tahun pendengaran telinga kanan menurun mendadak dengan rasa penuh setelah membersihkan telinga dengan cotton bud. Otoskopi: liang telinga kanan tersumbat total oleh massa padat cokelat. Rinne (–) kanan, Weber lateralisasi ke kanan. Jenis tulinya adalah…","opts":["Tuli sensorineural telinga kanan","Tuli sensorineural telinga kiri","Tuli konduktif telinga kanan","Tuli konduktif telinga kiri","Tuli campuran telinga kanan"],"ans":2,"why":"Serumen obturans (terdorong cotton bud) menyumbat liang telinga kanan. Rinne (–) dan Weber ke kanan menunjukkan tuli KONDUKTIF telinga kanan.","ref":[7,8],"tags":["Tes garpu tala","Serumen"],"skdi":"4A","src":"slide","cards":[]},
{"id":"tht-04","p":10,"stem":"Wanita 42 tahun pendengaran telinga kanan sangat berkurang; riwayat infeksi telinga berair berulang sejak kecil; hanya mendengar bila orang berteriak. Audiometri: ambang dengar rata-rata 80 dB. Derajat ketuliannya adalah…","opts":["Tuli ringan","Tuli sedang","Tuli sedang-berat","Tuli berat","Tuli sangat berat"],"ans":3,"why":"Derajat ketulian (ISO/WHO): 0–25 normal, 26–40 ringan, 41–55 sedang, 56–70 sedang-berat, 71–90 berat, > 90 sangat berat. 80 dB termasuk tuli BERAT.","ref":[9],"tags":["Derajat tuli"],"skdi":"4A","src":"slide","cards":[{"q":"Tuli berat = ambang dengar…?","a":"71–90 dB"},{"q":"Tuli ringan = ambang dengar…?","a":"26–40 dB"},{"q":"Tuli sedang = ambang dengar…?","a":"41–55 dB"}]},
{"id":"tht-05","p":15,"stem":"Laki-laki 30 tahun nyeri di depan telinga dengan benjolan kemerahan; sejak kecil ada lubang di depan telinga. Suhu 38,5°C. Massa preaurikula bengkak, hiperemis, fluktuasi (+). Tatalaksana yang tepat adalah…","opts":["Drainase","Drainase, analgetik, dan antibiotik","Antibiotik","Analgetik","Drainase dan antibiotik"],"ans":1,"why":"Fistula preaurikular yang terinfeksi menjadi ABSES (fluktuasi, demam): insisi dan drainase + antibiotik + analgetik. Eksisi fistula dilakukan setelah tenang.","ref":[12,13,14],"tags":["Fistula preaurikular"],"skdi":"3A","src":"slide","cards":[{"q":"Abses preaurikular: tatalaksana?","a":"Drainase + antibiotik + analgetik"}]},
{"id":"tht-06","p":15,"stem":"Wanita 18 tahun nyeri telinga kiri 2 hari, bengkak, keluar cairan kekuningan; riwayat tindik telinga di toko perhiasan. Diagnosis yang paling tepat adalah…","opts":["Mastoiditis","Perikondritis","Cauliflower ear","Abses preaurikula","Erisipelas"],"ans":1,"why":"Infeksi perikondrium daun telinga setelah tindik di area tulang rawan adalah perikondritis (sering Pseudomonas). Bila tidak diobati bisa berakhir sebagai cauliflower ear.","ref":[12,13,14],"tags":["Perikondritis"],"skdi":"3A","src":"slide","cards":[{"q":"Perikondritis aurikula: kuman tersering?","a":"Pseudomonas aeruginosa"}]},
{"id":"tht-07","p":15,"stem":"Anak perempuan 14 tahun keluar cairan dari lubang di depan telinga sejak kecil, tanpa nyeri atau bengkak. Patogenesis keluhan ini adalah…","opts":["Kegagalan penutupan duktus arteriosus","Kegagalan fusi segmen intermaksilaris","Kegagalan fusi arkus brankial","Kegagalan involusi duktus tiroglosus","Kegagalan pembentukan celah brankial"],"ans":2,"why":"Fistula preaurikular kongenital terjadi akibat kegagalan fusi tonjolan (hillocks of His) dari arkus brankial I dan II saat pembentukan aurikula.","ref":[12,13],"tags":["Fistula preaurikular"],"skdi":"3A","src":"slide","cards":[{"q":"Fistula preaurikular: patogenesis?","a":"Gagal fusi arkus brankial I & II"}]},
{"id":"tht-08","p":15,"stem":"Anak laki-laki 14 tahun nyeri telinga kanan 3 hari, keluar cairan dari lubang di depan daun telinga. Eritema daun telinga, benjolan hangat dan nyeri, fluktuasi (+); liang telinga normal. Diagnosisnya adalah…","opts":["Otitis eksterna sirkumskripta","Otitis eksterna difusa","Fistula preaurikular","Abses preaurikular","Furunkel"],"ans":3,"why":"Fistula preaurikular yang terinfeksi dengan benjolan berfluktuasi adalah abses preaurikular. Liang telinga normal, sehingga bukan otitis eksterna.","ref":[12,13,14],"tags":["Fistula preaurikular"],"skdi":"3A","src":"slide","cards":[]},
{"id":"tht-09","p":20,"stem":"Perempuan 30 tahun merasa ada yang bergerak di telinga kanan, terasa penuh. Tampak serangga HIDUP di liang telinga kanan. Tindakan pertama yang tepat adalah…","opts":["Ekstraksi dengan alligator forceps","Ekstraksi dengan hook","Ekstraksi dengan suction tip","Teteskan coconut oil 10 menit","Teteskan NaCl 5 menit"],"ans":3,"why":"Serangga HIDUP harus dimatikan dulu (diteteskan minyak, lidokain, atau alkohol sekitar 10 menit) agar tidak bergerak dan melukai membran timpani, baru diekstraksi atau diirigasi.","ref":[16,17],"tags":["Corpus alienum telinga"],"skdi":"4A","src":"coretan","cards":[{"q":"Serangga hidup di liang telinga: langkah pertama?","a":"Matikan dulu (teteskan minyak/lidokain)"}]},
{"id":"tht-10","p":20,"stem":"Wanita 20 tahun telinga kiri terasa penuh 2 hari dan berdenging setelah berenang; tanpa nyeri atau sekret. Serumen KERAS. Tatalaksana yang paling tepat adalah…","opts":["Antibiotik tetes telinga","Tetes karbogliserin 3 hari","Ekstraksi dengan hook","Ekstraksi dengan kapas lidi","Irigasi air hangat"],"ans":2,"why":"Kunci dosen: serumen KERAS → ekstraksi dengan hook (pengait). Serumen lunak → kapas lidi atau irigasi. Bila sangat keras dan sulit diangkat, dilunakkan dulu dengan karbogliserin 10% selama 3 hari.","ref":[16,17],"tags":["Serumen"],"skdi":"4A","src":"coretan","cards":[{"q":"Serumen keras: ekstraksi dengan…?","a":"Hook (pengait)"},{"q":"Serumen lunak: ekstraksi dengan…?","a":"Kapas lidi / irigasi"}]},
{"id":"tht-11","p":20,"stem":"Anak laki-laki 8 tahun nyeri telinga kanan 3 hari; sering berenang dan batuk pilek. Nyeri tekan tragus, nyeri tarik aurikula, meatus akustikus eksternus edema dan hiperemis (difus). Diagnosisnya adalah…","opts":["OMSK tipe benigna","OMA stadium hiperemis","OMA stadium supuratif","Otitis eksterna sirkumskripta","Otitis eksterna difusa"],"ans":4,"why":"Nyeri tekan tragus dan nyeri tarik aurikula dengan edema DIFUS liang telinga, setelah sering berenang (swimmer's ear), adalah otitis eksterna difusa (Pseudomonas). Sirkumskripta (furunkel) berupa benjolan lokal di 1/3 luar liang.","ref":[18],"tags":["Otitis eksterna"],"skdi":"4A","src":"coretan","cards":[{"q":"Otitis eksterna: tanda kunci?","a":"Nyeri tekan tragus & nyeri tarik aurikula"},{"q":"OE sirkumskripta?","a":"Benjolan (furunkel)"},{"q":"OE difusa?","a":"Edema liang telinga merata"}]},
{"id":"tht-12","p":20,"stem":"Laki-laki 28 tahun nyeri telinga kanan 5 hari tanpa penurunan pendengaran atau sekret. Nyeri tekan tragus, meatus akustikus SEMPIT, membran timpani tidak dapat dinilai. Tatalaksana yang tepat adalah…","opts":["Antibiotik oral","Tampon antibiotik","Tetes telinga antibiotik","Debridemen","Analgetik oral"],"ans":1,"why":"Otitis eksterna difusa dengan liang sangat sempit (edema): pasang tampon/wick yang dibasahi antibiotik dan steroid agar obat masuk dan edema berkurang, lalu tetes telinga. Antibiotik oral bila ada selulitis atau DM, atau curiga otitis eksterna maligna. (Catatan dosen.)","ref":[18],"tags":["Otitis eksterna"],"skdi":"4A","src":"coretan","cards":[{"q":"OE difusa dengan liang telinga sempit: tindakan?","a":"Tampon (wick) antibiotik"}]},
{"id":"tht-13","p":27,"stem":"Wanita 27 tahun keluar cairan dari telinga 3 bulan dengan penurunan pendengaran. Sekret purulen dan perforasi ATIK. Diagnosisnya adalah…","opts":["OME","OMA stadium perforasi","OMA stadium supurasi","OMSK tipe benigna","OMSK tipe maligna"],"ans":4,"why":"Otore > 2 bulan berarti OMSK. Perforasi ATIK atau marginal (biasanya disertai kolesteatoma) termasuk tipe MALIGNA (bahaya). Tipe benigna (aman): perforasi sentral.","ref":[22,24,25],"tags":["OMSK"],"skdi":"3A","src":"coretan","cards":[{"q":"OMSK maligna: letak perforasi?","a":"Atik / marginal (+ kolesteatoma)"},{"q":"OMSK benigna: letak perforasi?","a":"Sentral"},{"q":"OMSK = otore lebih dari…?","a":"2 bulan"}]},
{"id":"tht-14","p":27,"stem":"Wanita 23 tahun keluar cairan dari telinga kanan 1 hari; nyeri sebelumnya sudah berkurang, demam sudah membaik. Membran timpani perforasi (+). Tatalaksana yang tepat adalah…","opts":["Ofloksasin","Ampisilin","Neomisin","Polimiksin","Oksimetazolin"],"ans":0,"why":"OMA stadium PERFORASI (nyeri berkurang setelah ruptur MT, otore): cuci telinga H₂O₂ 3% dan tetes telinga ofloksasin (kuinolon, tidak ototoksik) + antibiotik oral. Neomisin dan polimiksin ototoksik bila MT perforasi.","ref":[23],"tags":["OMA"],"skdi":"4A","src":"coretan","cards":[{"q":"Tetes telinga aman bila MT perforasi?","a":"Ofloksasin"},{"q":"Stadium OMA (urutan)?","a":"Oklusi → hiperemis → supurasi → perforasi → resolusi"}]},
{"id":"tht-15","p":27,"stem":"Wanita 27 tahun keluar cairan dari telinga kanan 3 bulan dengan nyeri dan penurunan pendengaran. Otoskopi: MT perforasi di atik, sekret mukopurulen, tampak kolesteatoma. Komplikasi INTRATEMPORAL yang paling tepat adalah…","opts":["Meningitis","Selulitis","Perikondritis","Mastoiditis","Abses subperiosteal"],"ans":3,"why":"Komplikasi OMSK: intratemporal (mastoiditis, paresis N. VII, labirinitis, petrositis), ekstratemporal (abses subperiosteal/retroaurikular, Bezold), intrakranial (meningitis, abses otak, tromboflebitis sinus lateral).","ref":[25,26],"tags":["OMSK","Komplikasi"],"skdi":"3A","src":"coretan","cards":[{"q":"Contoh komplikasi intratemporal OMSK?","a":"Mastoiditis, paresis N. VII, labirinitis"},{"q":"Contoh komplikasi intrakranial OMSK?","a":"Meningitis, abses otak"}]},
{"id":"tht-16","p":27,"stem":"Laki-laki 45 tahun bengkak di sekitar telinga kanan; diawali keluar cairan dari telinga 5 bulan, nyeri, penurunan pendengaran. Edema dan hiperemis di area TEMPORAL dan meatus akustikus eksterna (fluktuatif). Diagnosisnya adalah…","opts":["Abses subperiosteal","Abses mastoid","Abses Bezold","Abses Luc","Abses Citelli"],"ans":3,"why":"Abses Luc: nanah menembus ke bawah m. temporalis atau ke dinding liang telinga, sehingga terjadi bengkak di area temporal dan meatus akustikus eksterna. Bezold: di bawah m. sternokleidomastoideus. Citelli: sepanjang venter posterior m. digastrikus. Subperiosteal: retroaurikular.","ref":[25,26],"tags":["OMSK","Abses"],"skdi":"3A","src":"coretan","cards":[{"q":"Abses Bezold: lokasi?","a":"Di bawah m. sternokleidomastoideus"},{"q":"Abses Luc: lokasi?","a":"Temporal / dinding liang telinga"},{"q":"Abses Citelli: lokasi?","a":"Venter posterior m. digastrikus"}]},
{"id":"tht-17","p":30,"stem":"Wanita 35 tahun pendengaran telinga kiri menurun bertahap 1 tahun; justru lebih mudah mendengar di lingkungan bising (mal). Otoskopi: MT intak normal. Rinne (–), Weber ke kiri. Temuan khas pada audiometri adalah…","opts":["Penurunan tajam di 4000 Hz","Pola cookie-bite di frekuensi tengah","Takik di frekuensi 2000 Hz","Penurunan landai di frekuensi tinggi","Tuli konduktif datar di semua frekuensi"],"ans":2,"why":"Otosklerosis: tuli konduktif progresif dengan MT normal dan parakusis Willisii (lebih jelas mendengar di tempat bising). Audiometri: Carhart notch (penurunan BC di 2000 Hz). Takik 4000 Hz: NIHL. Frekuensi tinggi landai: presbiakusis.","ref":[28,29],"tags":["Otosklerosis"],"skdi":"2","src":"coretan","cards":[{"q":"Carhart notch (2000 Hz) khas pada…?","a":"Otosklerosis"},{"q":"Parakusis Willisii?","a":"Lebih jelas mendengar di tempat bising (otosklerosis)"}]},
{"id":"tht-18","p":30,"stem":"Laki-laki 31 tahun pendengaran kedua telinga menurun sejak 2 bulan dan memberat; lebih baik di tempat ramai. Otoskopi seperti pada gambar (Schwartze sign: MT kemerahan). Audiometri: Carhart notch di 2000 Hz BC. Diagnosisnya adalah…","opts":["NIHL","Trauma akustik","Presbiakusis","Otosklerosis","Timpanosklerosis"],"ans":3,"why":"Carhart notch, parakusis Willisii, dan Schwartze sign (promontorium kemerahan terlihat dari balik MT) adalah otosklerosis (fiksasi stapes). Terapinya stapedektomi atau alat bantu dengar.","ref":[28,29],"tags":["Otosklerosis"],"skdi":"2","src":"coretan","img":true,"cards":[{"q":"Terapi otosklerosis?","a":"Stapedektomi / alat bantu dengar"}]},
{"id":"tht-19","p":30,"stem":"Anak perempuan 11 tahun pendengaran menurun 5 hari dengan batuk pilek. Tampak gelembung (bula) berdasar hiperemis pada membran timpani; nyeri tarik aurikula (–). Diagnosisnya adalah…","opts":["Otitis media akut","OMSK","Miringitis bulosa","Otitis media efusi","Otitis eksterna"],"ans":2,"why":"Bula (vesikel berisi cairan/darah) pada membran timpani setelah ISPA adalah miringitis bulosa (virus atau Mycoplasma).","ref":[28],"tags":["Miringitis bulosa"],"skdi":"2","src":"coretan","cards":[{"q":"Bula pada membran timpani?","a":"Miringitis bulosa"}]},
{"id":"tht-20","p":30,"stem":"Laki-laki 34 tahun pendengaran telinga kanan menurun 5 hari tanpa sekret atau nyeri; sering memakai headset. Pemeriksaan seperti pada gambar (bercak putih seperti kapur/plak kalsifikasi pada membran timpani). Diagnosis yang paling tepat adalah…","opts":["Otosklerosis","Timpanosklerosis","Presbiakusis","NIHL","Trauma akustik"],"ans":1,"why":"Kunci dosen (berdasarkan GAMBAR): plak putih kalsifikasi pada membran timpani adalah timpanosklerosis (deposit hialin/kalsium, biasanya sisa otitis media). Riwayat headset hanya pengecoh; NIHL tidak menimbulkan kelainan pada MT.","ref":[28,29],"tags":["Timpanosklerosis"],"skdi":"2","src":"coretan","img":true,"cards":[{"q":"Plak putih kalsifikasi di MT?","a":"Timpanosklerosis"}]},
{"id":"tht-21","p":35,"stem":"Wanita 20 tahun telinga kanan tidak bisa mendengar sejak semalam setelah menonton pentas seni kampus, berdenging; tanpa nyeri atau cairan. Diagnosisnya adalah…","opts":["NIHL","Trauma akustik","Presbiakusis","Otosklerosis","Timpanosklerosis"],"ans":1,"why":"Paparan bising sangat keras SEKALI (konser, ledakan) yang langsung menyebabkan tuli dan tinitus adalah trauma akustik. NIHL terjadi akibat paparan bising kronik berulang (bertahun-tahun, misalnya pabrik).","ref":[32,33,34],"tags":["Trauma akustik"],"skdi":"3A","src":"slide","cards":[{"q":"Trauma akustik?","a":"Bising sangat keras sekali (akut)"},{"q":"NIHL?","a":"Bising kronik bertahun-tahun"}]},
{"id":"tht-22","p":35,"stem":"Pria 65 tahun pendengaran kedua telinga menurun saat di tempat ramai sejak sebulan. Audiometri: AC dan BC turun di frekuensi TINGGI. Diagnosisnya adalah…","opts":["Otosklerosis","Timpanosklerosis","Presbiakusis","NIHL","Trauma akustik"],"ans":2,"why":"Tuli sensorineural bilateral simetris pada frekuensi tinggi pada lansia, terutama sulit mendengar di keramaian (cocktail party deafness), adalah presbiakusis.","ref":[32,33,34],"tags":["Presbiakusis"],"skdi":"4A","src":"slide","cards":[{"q":"Presbiakusis: audiogram?","a":"SNHL bilateral frekuensi tinggi (menurun landai)"}]},
{"id":"tht-23","p":35,"stem":"Pria 70 tahun pendengaran kedua telinga menurun beberapa bulan, terutama di keramaian. Audiometri: AC dan BC turun di frekuensi tinggi. Tatalaksana yang tepat adalah…","opts":["Terapi wicara","Alat bantu dengar","Timpanoplasti","Stapedektomi","Pelindung telinga"],"ans":1,"why":"Presbiakusis (degenerasi koklea, ireversibel) diterapi rehabilitasi dengan alat bantu dengar (hearing aid), ditambah latihan membaca bibir.","ref":[32,33,34],"tags":["Presbiakusis"],"skdi":"4A","src":"slide","cards":[{"q":"Terapi presbiakusis?","a":"Alat bantu dengar"}]},
{"id":"tht-24","p":35,"stem":"Laki-laki 45 tahun pendengaran kedua telinga berkurang perlahan 5 tahun dengan tinitus; operator mesin pabrik 20 tahun, jarang memakai pelindung telinga. Audiometri: takik khas di 4000 Hz. Diagnosisnya adalah…","opts":["Trauma akustik","Noise-induced hearing loss","Presbiakusis","Otosklerosis","Penyakit Meniere"],"ans":1,"why":"Paparan bising kronik (> 85 dB, bertahun-tahun) dengan takik (notch) audiogram di 4000 Hz adalah noise-induced hearing loss. Pencegahan: alat pelindung telinga.","ref":[32,33,34],"tags":["NIHL"],"skdi":"3A","src":"slide","cards":[{"q":"Takik audiogram 4000 Hz khas pada…?","a":"NIHL"}]},
{"id":"tht-25","p":42,"stem":"Wanita 25 tahun pusing berputar 30 menit, terutama saat berpindah posisi (bangun dari tempat tidur), mual muntah. Pemeriksaan fisik khusus yang tepat adalah…","opts":["Manuver Epley","Manuver Dix-Hallpike","Manuver half-somersault","Latihan Brandt-Daroff","Manuver Semont"],"ans":1,"why":"Vertigo singkat yang dicetuskan perubahan posisi kepala adalah BPPV. Tes DIAGNOSTIK: Dix-Hallpike (kanal posterior) atau supine roll test (kanal horizontal). Epley, Semont, dan Brandt-Daroff adalah manuver TERAPI (reposisi).","ref":[37,38,39,40],"tags":["BPPV","Vertigo"],"skdi":"4A","src":"coretan","cards":[{"q":"Tes diagnostik BPPV?","a":"Dix-Hallpike"},{"q":"Manuver terapi BPPV kanal posterior?","a":"Epley"}]},
{"id":"tht-26","p":42,"stem":"Laki-laki 37 tahun pusing berputar memberat sejak 20 menit, hilang timbul 2 bulan terutama saat bangun pagi; tanpa tinitus, gangguan dengar, atau trauma. Nistagmus horizontal. Tatalaksana yang tepat adalah…","opts":["Analgetik","Kortikosteroid","Antibiotik","Antihistamin","Antiepilepsi"],"ans":3,"why":"BPPV atau vertigo perifer akut: simtomatik dengan antihistamin (betahistin, dimenhidrinat, flunarizin) sebagai sedatif vestibular, ditambah manuver reposisi. Kortikosteroid untuk neuritis vestibular.","ref":[39,40,41],"tags":["BPPV","Vertigo"],"skdi":"4A","src":"coretan","cards":[{"q":"Obat simtomatik vertigo perifer?","a":"Antihistamin (betahistin, dimenhidrinat)"}]},
{"id":"tht-27","p":42,"stem":"Wanita 25 tahun pusing berputar 1 jam disertai telinga berdenging dan penurunan pendengaran. Tanpa defisit neurologis. Nistagmus horizontal (+), Romberg tertutup (+). Diagnosisnya adalah…","opts":["Vertigo sentral","Motion sickness","BPPV","Penyakit Meniere","Labirinitis"],"ans":3,"why":"Trias Meniere: vertigo episodik (20 menit–12 jam), tinitus, tuli sensorineural fluktuatif (± rasa penuh) akibat hidrops endolimfe. Labirinitis didahului infeksi telinga dan vertigo berlangsung berhari-hari. BPPV tanpa gangguan pendengaran.","ref":[38,39,40],"tags":["Meniere","Vertigo"],"skdi":"3A","src":"coretan","cards":[{"q":"Trias Meniere?","a":"Vertigo + tinitus + tuli sensorineural"},{"q":"Patofisiologi Meniere?","a":"Hidrops endolimfe"}]},
{"id":"tht-28","p":42,"stem":"Wanita 22 tahun pusing berputar sangat berat 1 jam dengan telinga berdenging; riwayat infeksi telinga. Tanpa defisit neurologis. Nistagmus horizontal (+), Romberg tertutup (+), Romberg terbuka (–). Diagnosis yang tepat adalah…","opts":["Vertigo sentral","Vertigo perifer","Sefalgia primer","Sefalgia sekunder","Motion sickness"],"ans":1,"why":"Vertigo dengan gejala telinga (tinitus, riwayat infeksi telinga yang mengarah ke labirinitis), nistagmus horizontal, Romberg positif hanya saat mata tertutup, dan tanpa defisit neurologis adalah vertigo PERIFER. Vertigo sentral: nistagmus vertikal atau multiarah dan ada defisit neurologis.","ref":[37,38,40],"tags":["Vertigo"],"skdi":"4A","src":"coretan","cards":[{"q":"Vertigo sentral: nistagmus?","a":"Vertikal / berubah arah"},{"q":"Vertigo perifer: nistagmus?","a":"Horizontal(-rotatoar), satu arah"}]},
{"id":"tht-29","p":55,"stem":"Wanita 22 tahun pilek 2 minggu; hidung tersumbat hilang timbul 6 bulan hampir setiap hari, terutama pagi dan saat hujan, rinore dan bersin; ibu dan kakak sama. Allergic crease (+); rinoskopi: mukosa edema, basah, sekret bening. Tatalaksana yang tepat adalah…","opts":["Cetirizin 1×5 mg + flutikason spray 1×1 puff","Cetirizin 1×5 mg + flutikason spray 1×2 puff","Cetirizin 1×10 mg + flutikason spray 1×2 puff","Cetirizin 1×10 mg + flutikason spray 1×1 puff","Cetirizin 1×5 mg + flutikason spray 1×1 puff"],"ans":2,"why":"Rinitis alergi persisten sedang-berat pada dewasa: antihistamin H1 generasi 2 dosis dewasa (cetirizin 10 mg sekali sehari) + kortikosteroid intranasal (flutikason 2 semprot per lubang hidung sekali sehari).","ref":[45,46,47,48],"tags":["Rinitis alergi"],"skdi":"4A","src":"coretan","cards":[{"q":"Dosis cetirizin dewasa?","a":"10 mg sekali sehari"},{"q":"Dosis flutikason intranasal dewasa?","a":"2 semprot/lubang 1×/hari"}]},
{"id":"tht-30","p":55,"stem":"Wanita 37 tahun hidung tersumbat hilang timbul 5 tahun, awalnya kanan lalu keduanya; pusing dan nyeri di daerah pipi. Pemeriksaan FISIK yang tepat adalah…","opts":["Rinoskopi anterior","Rinoskopi posterior","Laringoskopi","CT scan kepala","Foto rontgen"],"ans":0,"why":"Curiga rinosinusitis kronik (± polip). Pemeriksaan FISIK awal: rinoskopi anterior (sekret di meatus medius, polip), transiluminasi sinus, dan nyeri tekan wajah. CT scan dan rontgen adalah pemeriksaan PENUNJANG.","ref":[51,52,53,54],"tags":["Rinosinusitis"],"skdi":"4A","src":"coretan","cards":[{"q":"Gold standard penunjang rinosinusitis kronik?","a":"CT scan sinus paranasal"}]},
{"id":"tht-31","p":55,"stem":"Wanita 22 tahun hidung tersumbat 2 hari yang selalu muncul setiap menstruasi; tanpa alergi debu atau dingin, tanpa demam. Konka merah tua, edema, sekret mukoid. Diagnosisnya adalah…","opts":["Rinitis alergi","Rinitis vasomotor","Rinitis medikamentosa","Rinosinusitis akut","Rinosinusitis kronik"],"ans":1,"why":"Rinitis vasomotor (nonalergi) dicetuskan faktor nonspesifik: perubahan hormonal (menstruasi, hamil), suhu, iritan, emosi, atau obat. Konka merah gelap dan edema. Rinitis alergi: konka pucat livid.","ref":[46,49],"tags":["Rinitis vasomotor"],"skdi":"4A","src":"coretan","cards":[{"q":"Rinitis vasomotor: konka?","a":"Merah gelap/tua"},{"q":"Rinitis alergi: konka?","a":"Pucat livid"}]},
{"id":"tht-32","p":55,"stem":"Wanita 24 tahun tidak dapat mencium bau sejak 4 hari, hidung tersumbat; bersin pagi disangkal. Rongga hidung tampak ATROFI dengan sekret kuning kehijauan BERBAU. Diagnosisnya adalah…","opts":["Rinitis alergi","Rinitis vasomotor","Rinitis ozaena","Rinitis akut bakterial","Rinitis medikamentosa"],"ans":2,"why":"Rinitis atrofi (ozaena): mukosa dan konka atrofi, rongga hidung lapang, krusta atau sekret hijau sangat berbau (pasien sendiri anosmia, tidak menciumnya). Sering oleh Klebsiella ozaenae.","ref":[49],"tags":["Rinitis atrofi"],"skdi":"3A","src":"coretan","cards":[{"q":"Rinitis ozaena: tanda khas?","a":"Mukosa atrofi + krusta hijau berbau"}]},
{"id":"tht-33","p":61,"stem":"Anak perempuan 13 tahun mimisan 4 jam; ibu sudah mencoba Trotter (menekan hidung) tetapi tidak berhenti. Riwayat mimisan berulang dan gangguan darah. Perdarahan aktif mengalir ke tenggorok, sumber sulit dievaluasi. Tatalaksana yang tepat adalah…","opts":["Tampon anterior","Tampon Bellocq","Tekan hidung 20 menit","Elevasi kepala","Asam traneksamat"],"ans":1,"why":"Darah mengalir ke tenggorok dan tidak berhenti dengan penekanan menunjukkan epistaksis POSTERIOR (a. sfenopalatina). Terapinya tampon posterior (Bellocq atau kateter Foley). Tampon anterior untuk epistaksis anterior (pleksus Kiesselbach).","ref":[56],"tags":["Epistaksis"],"skdi":"4A","src":"coretan","cards":[{"q":"Epistaksis posterior: tampon?","a":"Bellocq (posterior)"},{"q":"Sumber epistaksis anterior?","a":"Pleksus Kiesselbach"},{"q":"Sumber epistaksis posterior?","a":"A. sfenopalatina"}]},
{"id":"tht-34","p":61,"stem":"Wanita 29 tahun nyeri hidung 5 hari, hidung kemerahan. Nyeri tekan (+), teraba hangat, Rudolph sign (+). Diagnosisnya adalah…","opts":["Korpus alienum nasi","Karbunkel nasi","Furunkel nasi","Vestibulitis","Dermatitis"],"ans":2,"why":"Infeksi folikel rambut vestibulum nasi (S. aureus) dengan Rudolph sign (nyeri saat ujung hidung ditekan) adalah furunkel nasi. Jangan dipencet (danger triangle, risiko trombosis sinus kavernosus).","ref":[57],"tags":["Furunkel nasi"],"skdi":"4A","src":"coretan","cards":[{"q":"Rudolph sign (+) pada…?","a":"Furunkel nasi"},{"q":"Bahaya memencet furunkel di segitiga bahaya wajah?","a":"Trombosis sinus kavernosus"}]},
{"id":"tht-35","p":61,"stem":"Wanita 40 tahun hidung kiri tersumbat 1 bulan, sulit bernapas. Massa licin hampir menutupi seluruh meatus, hanya tersisa sedikit celah, hiperemis (–). Derajat polip nasi menurut dosen adalah…","opts":["Stadium 0","Stadium 1","Stadium 2","Stadium 3","Stadium 4"],"ans":4,"why":"Kunci dosen: massa polip yang hampir memenuhi rongga hidung (menutupi seluruh meatus) termasuk stadium tertinggi pada pembagian yang dipakai di slide. Cocokkan dengan tabel stadium polip di slide 60.","ref":[60],"tags":["Polip nasi"],"skdi":"3A","src":"coretan","cards":[{"q":"Polip nasi: ciri klinis?","a":"Massa licin, pucat, tidak nyeri, tidak berdarah saat disentuh"}]},
{"id":"tht-36","p":61,"stem":"Laki-laki 21 tahun nyeri kepala 1 minggu, hidung tersumbat hilang timbul sejak lama; sinusitis berulang. Rinoskopi anterior: septum tampak tidak lurus. Diagnosisnya adalah…","opts":["Deviasi septum","Abses septum","Trauma hidung","Hematoma septum","Fraktur os nasal"],"ans":0,"why":"Septum nasi yang bengkok menyebabkan sumbatan hidung kronik dan gangguan drenase sinus (sinusitis berulang): deviasi septum. Terapinya septoplasti bila simtomatik.","ref":[58,60],"tags":["Deviasi septum"],"skdi":"3A","src":"coretan","cards":[{"q":"Terapi deviasi septum simtomatik?","a":"Septoplasti"}]},
{"id":"tht-37","p":74,"stem":"Anak laki-laki 11 tahun demam 3 hari, nyeri menelan; keluhan serupa 5–7× per tahun selama hampir 2 tahun. Kini sering terbangun malam dan sulit bernapas. Tonsil T3–T4, detritus (+), halitosis (+). Indikasi ABSOLUT tonsilektomi adalah…","opts":["Tonsilitis kronik berulang","> 3× episode per tahun walau dengan antibiotik","Halitosis","Tonsilitis derajat 3–4","OSAS"],"ans":4,"why":"Indikasi absolut tonsilektomi: obstruksi jalan napas (OSAS, sleep apnea dengan cor pulmonale), abses peritonsil, tonsilitis yang menimbulkan kejang demam, dan curiga keganasan. Tonsilitis berulang dan halitosis adalah indikasi relatif.","ref":[67,68,69],"tags":["Tonsilitis","Tonsilektomi"],"skdi":"4A","src":"coretan","cards":[{"q":"Indikasi absolut tonsilektomi?","a":"OSAS/obstruksi napas, abses peritonsil, kejang demam, curiga keganasan"}]},
{"id":"tht-38","p":74,"stem":"Laki-laki 19 tahun nyeri tenggorok 3 hari terutama saat makan dan minum, batuk, hidung tersumbat, demam > 38°C 2 hari. Faring hiperemis. Pemeriksaan penunjang yang tepat adalah…","opts":["Darah lengkap","Kultur dahak","Kultur swab tenggorok","Rontgen toraks","Titer antistreptolisin"],"ans":2,"why":"Faringitis akut dengan kecurigaan bakteri (GABHS): baku emas diagnosis etiologi adalah kultur swab tenggorok (atau rapid antigen test). ASTO menunjukkan infeksi sebelumnya, bukan diagnosis akut.","ref":[70],"tags":["Faringitis"],"skdi":"4A","src":"coretan","cards":[{"q":"Baku emas diagnosis faringitis GABHS?","a":"Kultur swab tenggorok"}]},
{"id":"tht-39","p":74,"stem":"Anak 8 tahun nyeri menelan 3 hari, batuk, demam. Tonsil hiperemis T2–T2 dengan PSEUDOMEMBRAN yang mudah berdarah bila diangkat. Etiologinya adalah…","opts":["Staphylococcus aureus","Corynebacterium diphtheriae","Clostridium botulinum","Clostridium tetani","Haemophilus influenzae tipe B"],"ans":1,"why":"Pseudomembran putih keabuan yang melekat dan BERDARAH bila diangkat (± bull neck) adalah difteri tonsil oleh Corynebacterium diphtheriae. Terapi: ADS + penisilin/eritromisin.","ref":[72],"tags":["Difteri"],"skdi":"3B","src":"coretan","cards":[{"q":"Pseudomembran berdarah saat diangkat?","a":"Difteri"},{"q":"Terapi difteri?","a":"ADS + penisilin/eritromisin"}]},
{"id":"tht-40","p":74,"stem":"Anak laki-laki 8 tahun demam 6 hari, nyeri menelan. Tonsil hiperemis, pseudomembran (+) mudah berdarah. Pemeriksaan penunjang yang tepat adalah…","opts":["Pewarnaan Ziehl-Neelsen","Kultur bakteri","Tzanck test","Rontgen","Darah lengkap"],"ans":1,"why":"Konfirmasi difteri: swab di bawah pseudomembran untuk pewarnaan Gram/Neisser dan KULTUR (media Loeffler/telurit), ditambah uji toksigenisitas (Elek). (Catatan dosen: difteri, kultur.)","ref":[72],"tags":["Difteri"],"skdi":"3B","src":"coretan","cards":[{"q":"Media kultur difteri?","a":"Loeffler / telurit"}]},
{"id":"tht-41","p":81,"stem":"Anak perempuan 6 tahun sulit menelan 5 hari, demam tinggi, batuk. Suhu 40°C, stridor inspirasi, bibir dan ekstremitas sianosis. Radiologi: thumb print sign dan vallecula sign. Etiologinya adalah…","opts":["Adenovirus","Haemophilus influenzae","Parainfluenza","Enterovirus","Rhinovirus"],"ans":1,"why":"Thumb print sign (epiglotis bengkak) dengan disfagia, drooling, stridor, dan demam tinggi adalah epiglotitis akut oleh H. influenzae tipe b. Croup disebabkan parainfluenza (steeple sign).","ref":[75,76],"tags":["Epiglotitis"],"skdi":"3B","src":"slide","cards":[]},
{"id":"tht-42","p":81,"stem":"Wanita 28 tahun guru, suara serak 3 bulan, lebih berat dan mudah lelah setelah mengajar, membaik saat akhir pekan; tanpa demam, nyeri menelan, atau BB turun. Laringoskopi: penebalan kecil putih SIMETRIS di kedua pita suara pada perbatasan 1/3 anterior dan 2/3 posterior. Tatalaksana awal yang paling tepat adalah…","opts":["Eksisi bedah mikro","Injeksi kortikosteroid intralesi","Antibiotik empiris","Terapi suara","PPI"],"ans":3,"why":"Nodul pita suara (singer's/teacher's nodule) akibat penyalahgunaan suara, bilateral simetris di 1/3 anterior–tengah. Lini pertama: terapi suara (voice therapy) dan istirahat suara. Operasi bila gagal.","ref":[75,76],"tags":["Nodul pita suara"],"skdi":"2","src":"slide","cards":[{"q":"Nodul pita suara: lokasi?","a":"Bilateral, batas 1/3 anterior & 2/3 posterior"},{"q":"Nodul pita suara: terapi awal?","a":"Terapi suara"}]},
{"id":"tht-43","p":81,"stem":"Pria 35 tahun suara hilang mendadak sejak 1 hari; 2 hari sebelumnya demam ringan, hidung tersumbat, nyeri tenggorok; tidak merokok. Suhu 37,9°C, suara seperti bisikan kasar. Laringoskopi: kedua pita suara bengkak dan sangat merah difus. Edukasi yang paling penting adalah…","opts":["Segera antibiotik spektrum luas","Hindari makanan terlalu panas atau dingin","Kumur antiseptik sesering mungkin","Istirahat suara total","Fisioterapi otot laring"],"ans":3,"why":"Laringitis akut (umumnya virus, pasca-ISPA) bersifat self-limiting. Edukasi terpenting: istirahat suara total (vocal rest), hidrasi, dan hindari iritan. Antibiotik tidak rutin.","ref":[75,76],"tags":["Laringitis"],"skdi":"4A","src":"slide","cards":[{"q":"Laringitis akut: terapi utama?","a":"Istirahat suara total"}]},
{"id":"tht-44","p":81,"stem":"Wanita 52 tahun suara serak hilang timbul 6 bulan, lebih berat saat bangun pagi, sering berdeham, rasa mengganjal di leher; tanpa nyeri ulu hati atau heartburn. Laringoskopi: edema dan eritema di regio aritenoid dan interaritenoid, penebalan mukosa komisura posterior. Diagnosis yang paling mungkin adalah…","opts":["Nodul pita suara","Laringitis TB","Karsinoma laring","GERD","Laryngopharyngeal reflux"],"ans":4,"why":"Refluks laringofaring (LPR, 'silent reflux'): suara serak, sering berdeham, globus, sering TANPA heartburn. Laringoskopi menunjukkan edema dan eritema aritenoid dan interaritenoid serta hipertrofi komisura posterior. Terapinya PPI dosis ganda dan modifikasi gaya hidup.","ref":[77,78,79],"tags":["LPR"],"skdi":"3A","src":"slide","cards":[{"q":"LPR: lokasi kelainan di laring?","a":"Aritenoid / komisura posterior"},{"q":"LPR: terapi?","a":"PPI dosis ganda + gaya hidup"}]},
{"id":"tht-45","p":86,"stem":"Anak demam dan sakit hebat saat menelan 5 hari sehingga tidak mau makan, napas berbau. Tonsil kanan sangat bengkak (T3) dan merah, tonsil kiri T2; uvula terdorong ke kiri; area di atas tonsil kanan lunak dan berfluktuasi. Pemeriksaan penunjang yang tepat untuk diagnosis adalah…","opts":["Kultur saliva","Aspirasi pus","CT scan kepala","Kultur darah","CT scan leher"],"ans":1,"why":"Abses peritonsil (quinsy): pembengkakan supratonsil unilateral, uvula terdorong ke sisi sehat, trismus, hot potato voice. Diagnosis dan terapi dengan aspirasi jarum (pus +), lalu insisi drainase dan antibiotik.","ref":[82,83,84,85],"tags":["Abses peritonsil"],"skdi":"3A","src":"slide","cards":[{"q":"Abses peritonsil: uvula?","a":"Terdorong ke sisi sehat"},{"q":"Abses peritonsil: diagnosis & terapi?","a":"Aspirasi pus lalu insisi drainase"}]},
{"id":"tht-46","p":86,"stem":"Laki-laki 40 tahun sesak; sebelumnya rahang bawah bengkak dan leher nyeri, demam, sulit menelan. Massa dari submandibula, submental, hingga subklavikula; sisa akar gigi geraham bawah dan gingiva bengkak. Diagnosis dan terapi yang tepat adalah…","opts":["Angina Ludovici, antibiotik","Abses mandibula, insisi","Abses parafaring, obat kumur","Abses retrofaring, pungsi","Abses peritonsil, tonsilektomi"],"ans":0,"why":"Selulitis atau abses ruang submandibula bilateral, submental, dan sublingual yang berasal dari infeksi gigi molar bawah adalah angina Ludovici. Kegawatan jalan napas: amankan airway, antibiotik IV dosis tinggi, dan insisi dekompresi bila ada abses.","ref":[82,83,84,85],"tags":["Angina Ludovici","Abses leher dalam"],"skdi":"3A","src":"slide","cards":[{"q":"Sumber infeksi angina Ludovici?","a":"Gigi molar bawah"}]},
{"id":"tht-47","p":86,"stem":"Anak laki-laki 5 tahun demam, rewel, tidak mau makan 2 hari; sebelumnya tertelan duri ikan. Napas mengorok, banyak liur keluar. Dinding belakang faring membengkak unilateral menonjol ke depan. Diagnosis yang paling sesuai adalah…","opts":["Abses submandibula","Abses peritonsil","Epiglotitis akut","Abses parafaring","Abses retrofaring"],"ans":4,"why":"Penonjolan dinding POSTERIOR faring, terutama pada anak < 5 tahun (kelenjar limfe retrofaring masih ada), pascatrauma tusuk atau ISPA, adalah abses retrofaring. Rontgen leher lateral: jaringan lunak prevertebra melebar.","ref":[82,83,84,85],"tags":["Abses retrofaring"],"skdi":"3A","src":"slide","cards":[{"q":"Abses retrofaring: temuan khas?","a":"Dinding posterior faring menonjol"}]},
{"id":"tht-48","p":86,"stem":"Mahasiswa 20 tahun nyeri tenggorok hebat sisi kanan 3 hari, demam, lemas, bau mulut sangat mengganggu; stres ujian, kebersihan mulut buruk. Suhu 38,5°C; tonsil kanan bengkak dan hiperemis tertutup selaput tebal kuning yang mudah dilepas dan tidak mudah berdarah; tonsil kiri normal. Mikroorganisme penyebab yang paling mungkin adalah…","opts":["Streptococcus pyogenes","Corynebacterium diphtheriae","Kombinasi Fusobacterium dan Spirochaeta","Epstein-Barr virus","Candida albicans"],"ans":2,"why":"Angina Plaut-Vincent: tonsilitis ulseromembranosa unilateral dengan halitosis berat pada orang dengan higiene mulut buruk atau stres, akibat simbiosis Fusobacterium dan spiroketa (Borrelia vincentii). Membrannya mudah dilepas tanpa berdarah (beda dengan difteri).","ref":[67,70],"tags":["Angina Vincent"],"skdi":"3A","src":"slide","cards":[{"q":"Angina Plaut-Vincent: penyebab?","a":"Fusobacterium + spiroketa"}]},
{"id":"tht-49","p":91,"stem":"Pria 36 tahun benjolan leher kanan 2 bulan makin membesar, nyeri kepala, suara serak, sulit menelan dan bernapas; BB turun 15 kg dalam 2 bulan. Diagnosis yang tepat adalah…","opts":["Ca nasofaring","Ca laring","Ca sinonasal","Limfoma Hodgkin","Limfoma non-Hodgkin"],"ans":0,"why":"Benjolan leher (KGB servikal atas, sering gejala pertama) dengan nyeri kepala dan gejala kompresi atau ekspansi menunjukkan karsinoma nasofaring (EBV). Ca nasofaring adalah keganasan kepala-leher tersering di Indonesia. (Catatan dosen: telinga dan leher.)","ref":[88,89,90],"tags":["Ca nasofaring"],"skdi":"2","src":"coretan","cards":[{"q":"Gejala pertama tersering Ca nasofaring?","a":"Benjolan leher (KGB servikal)"},{"q":"Virus terkait Ca nasofaring?","a":"Epstein-Barr virus"}]},
{"id":"tht-50","p":91,"stem":"Remaja laki-laki 15 tahun mimisan berulang 6 bulan, tiba-tiba dan sulit berhenti; hidung tersumbat satu sisi yang makin berat. Rinoskopi: massa lunak merah kebiruan. Diagnosis yang paling mungkin adalah…","opts":["Karsinoma nasofaring","Polip nasi","Rinitis alergi","Juvenile nasopharyngeal angiofibroma","Karsinoma sinonasal"],"ans":3,"why":"Remaja laki-laki dengan epistaksis berulang masif, sumbatan hidung unilateral, dan massa merah keunguan (vaskular) adalah juvenile nasopharyngeal angiofibroma (JNA). Biopsi DIKONTRAINDIKASIKAN karena risiko perdarahan hebat.","ref":[88,89,90],"tags":["JNA"],"skdi":"2","src":"coretan","cards":[{"q":"JNA: profil pasien?","a":"Remaja laki-laki + epistaksis berulang"},{"q":"JNA: kontraindikasi tindakan?","a":"Biopsi (risiko perdarahan)"}]},
{"id":"tht-51","p":91,"stem":"Laki-laki 65 tahun hidung kanan tersumbat terus 6 bulan tidak membaik dengan obat, mimisan sesekali di sisi yang sama, nyeri dan mati rasa pipi kanan; pengrajin mebel kayu 30 tahun. Massa seperti daging mudah berdarah di rongga hidung kanan. Diagnosis yang paling patut dicurigai adalah…","opts":["Sinusitis jamur alergika","Karsinoma sinonasal","Polip antrokoana","Karsinoma nasofaring","Juvenile nasopharyngeal angiofibroma"],"ans":1,"why":"Paparan debu kayu (adenokarsinoma etmoid) atau nikel, dengan sumbatan dan epistaksis unilateral serta parestesia pipi (N. V2 terinfiltrasi), mengarah ke karsinoma sinonasal.","ref":[88,89,90],"tags":["Ca sinonasal"],"skdi":"2","src":"coretan","cards":[{"q":"Faktor risiko pekerjaan Ca sinonasal?","a":"Debu kayu / nikel"}]},
{"id":"tht-52","p":91,"stem":"Anak laki-laki 16 tahun hidung kanan tersumbat 5 bulan makin berat, mimisan berulang, nyeri kepala hilang timbul. Massa merah kebiruan mengilat di hidung (JNA). Tatalaksana yang tepat adalah…","opts":["Tampon anterior","Reseksi bedah","Insisi dan drainase","Polipektomi","Biopsi"],"ans":1,"why":"Terapi definitif JNA (tumor jinak tetapi agresif lokal) adalah reseksi bedah (endoskopik/terbuka), sering didahului embolisasi preoperatif. Biopsi dikontraindikasikan.","ref":[88,89,90],"tags":["JNA"],"skdi":"2","src":"coretan","cards":[{"q":"Terapi definitif JNA?","a":"Reseksi bedah (± embolisasi)"}]},
{"id":"tht-x01","lat":"fk-matatht","ln":101,"lp":84,"stem":"Perempuan 18 tahun dengan pilek terus-menerus sejak 5 tahun; ingus kental kehijauan, kadang keluar kerak, dan suami mengeluhkan bau dari hidung pasien. Sebulan terakhir penciuman terganggu. Riwayat bersin/alergi disangkal. Rinoskopi anterior: rongga hidung lapang, konka atrofi, krusta kehijauan. Apakah diagnosis dan tatalaksana yang tepat?","opts":["Rinitis alergi dan antihistamin","Rinitis medikamentosa dan kortikosteroid intranasal","Rinitis ozaena dan tampon gliserin + antibiotik sesuai kultur","Rinitis vasomotor dan neurektomi n. vidianus","Rinitis atrofikans dan dekongestan"],"ans":2,"why":"Rinitis atrofi/ozaena (Klebsiella ozaenae): rongga hidung lapang, konka atrofi, krusta hijau berbau, anosmia. Terapi: cuci hidung, tampon gliserin (melembapkan, mengangkat krusta) + antibiotik sesuai kultur. Dekongestan memperburuk atrofi.","ref":[49],"tags":["Rinitis atrofi"],"skdi":"3A","src":"kunci","cards":[{"q":"Penyebab rinitis ozaena?","a":"Klebsiella ozaenae"},{"q":"Terapi rinitis ozaena?","a":"Cuci hidung, tampon gliserin + antibiotik"}],"xp":[85,86]},
{"id":"tht-x02","lat":"fk-matatht","ln":102,"lp":89,"stem":"Perempuan 25 tahun dengan penurunan pendengaran telinga kanan dan tinitus sejak 2 minggu; pendengaran membaik saat berada di tempat ramai. Otoskopi seperti gambar. Audiometri: Carhart notch di 2000 Hz. Apakah diagnosis yang tepat?","opts":["Otosklerosis","Timpanosklerosis","Otitis media efusi","Otitis media akut","Otitis media supuratif kronik"],"ans":0,"why":"Paracusis Willisii (mendengar lebih baik di tempat ramai) + Carhart notch 2000 Hz pada wanita muda → otosklerosis (fiksasi stapes). Otoskopi biasanya normal (± Schwartze sign).","ref":[28,29],"tags":["Otosklerosis"],"skdi":"2","src":"kunci","cards":[{"q":"Schwartze sign?","a":"Bercak kemerahan promontorium (otosklerosis aktif)"}],"img":true,"xp":[90,91]},
{"id":"tht-x03","lat":"fk-matatht","ln":103,"lp":93,"stem":"Anak laki-laki 13 tahun dengan penurunan pendengaran dan telinga terasa penuh sejak 3 minggu; tanpa gatal, nyeri, atau cairan. Sering mengorek telinga dengan cotton bud. Otoskopi: serumen keras menutupi seluruh liang telinga. Dokter sudah mencoba mengambil dengan pengait namun gagal. Apakah tatalaksana yang tepat?","opts":["Ekstraksi serumen dengan kapas lilit","Ekstraksi serumen dengan hook","Ekstraksi serumen setelah pemberian karbogliserin 10% terlebih dahulu selama 3 hari","Ekstraksi serumen dengan kuret","Irigasi dengan air hangat"],"ans":2,"why":"Serumen keras/obturans yang GAGAL diambil dengan pengait → lunakkan dulu dengan karbogliserin 10% (tetes 3 hari), lalu ekstraksi/irigasi.","ref":[16,17],"tags":["Serumen"],"skdi":"4A","src":"kunci","cards":[{"q":"Serumen keras gagal dikait: langkah?","a":"Lunakkan dengan karbogliserin 10% selama 3 hari"}],"xp":[94,95]},
{"id":"tht-x04","lat":"fk-matatht","ln":104,"lp":96,"stem":"Laki-laki 50 tahun dengan keluar cairan telinga hilang timbul sejak 6 bulan, memberat disertai nyeri sejak 1 bulan; riwayat batuk pilek 7 bulan lalu. Otoskopi: perforasi membran timpani di atik; foto Schüller: kolesteatoma. Apakah tatalaksana yang tepat?","opts":["Grommet tube","Antibiotik","Miringotomi","Mastoidektomi","Timpanoplasti"],"ans":3,"why":"OMSK tipe bahaya (maligna): perforasi atik/marginal + kolesteatoma → terapi definitif operasi mastoidektomi (eradikasi kolesteatoma) ± timpanoplasti. Antibiotik hanya tambahan.","ref":[24,25,26],"tags":["OMSK maligna"],"skdi":"3A","src":"kunci","cards":[{"q":"OMSK dengan kolesteatoma: terapi?","a":"Mastoidektomi"},{"q":"Foto untuk mastoid?","a":"Schüller"}],"xp":[97,98]},
{"id":"tht-x05","lat":"fk-matatht","ln":105,"lp":101,"stem":"Perempuan 35 tahun dengan lendir hijau berbau dari hidung sejak 2 minggu, nyeri pipi kiri, hidung tersumbat, dan lendir di tenggorok. Nyeri ketok pipi kiri, konka edema, pus purulen, post-nasal drip (+). Manakah pemeriksaan foto yang tepat untuk memvisualisasikan sinus maksila?","opts":["Foto Waters","Foto Schedel AP dan lateral","Foto Schüller","Foto Stenvers","CT scan"],"ans":0,"why":"Rinosinusitis maksila. Proyeksi foto polos terbaik untuk sinus maksila: Waters (occipitomental). Schüller = mastoid; Stenvers = kanalis akustikus interna/petrosus. Baku emas pencitraan sinus: CT scan.","ref":[51,52,92],"tags":["Rinosinusitis","Radiologi"],"skdi":"4A","src":"kunci","cards":[{"q":"Foto Waters untuk…?","a":"Sinus maksila"},{"q":"Foto Stenvers untuk…?","a":"Os petrosus / kanalis akustikus interna"},{"q":"Foto Caldwell untuk…?","a":"Sinus frontal & etmoid"}],"xp":[102,103]},
{"id":"tht-x06","lat":"fk-matatht","ln":106,"lp":105,"stem":"Anak laki-laki 6 tahun sering mendengkur saat tidur dan sering pilek. Tampak hidung kecil, mulut terbuka, mata sayu; gigi insisivus menonjol, tonsil tidak membesar, tenggorok normal, palatum (arkus faring) tinggi. Apakah diagnosis pasien?","opts":["Obstructive sleep apnea","Hipertrofi adenoid","Angiofibroma nasofaring juvenil","Sinusitis","Tonsilitis kronik"],"ans":1,"why":"Adenoid face (facies adenoid): mulut terbuka, hidung kecil, mata sayu, palatum tinggi, gigi insisivus menonjol + mendengkur pada anak dengan tonsil normal → hipertrofi adenoid. Rontgen: soft tissue nasofaring lateral (rasio adenoid-nasofaring).","ref":[73],"tags":["Hipertrofi adenoid"],"skdi":"3A","src":"kunci","cards":[{"q":"Facies adenoid?","a":"Mulut terbuka, palatum tinggi, gigi insisivus menonjol"}],"xp":[106,107]},
{"id":"tht-x07","lat":"fk-matatht","ln":107,"lp":108,"stem":"Anak laki-laki 14 tahun dengan mimisan berulang sejak usia 10 tahun, disertai penurunan penciuman dan hidung tersumbat; riwayat trauma disangkal. Rinoskopi posterior: massa lunak, mudah berdarah, berwarna abu-abu kemerahan di nasofaring. Apakah diagnosis yang sesuai?","opts":["Angiofibroma nasofaring juvenil","Kanker nasofaring","Tonsilitis kronik","Hipertrofi adenoid","Epistaksis anterior berulang"],"ans":0,"why":"Remaja laki-laki + epistaksis berulang + sumbatan hidung + massa nasofaring mudah berdarah → juvenile nasopharyngeal angiofibroma. Biopsi dikontraindikasikan.","ref":[88,90],"tags":["JNA"],"skdi":"2","src":"kunci","cards":[],"xp":[109,110]},
{"id":"tht-x08","lat":"fk-matatht","ln":108,"lp":111,"stem":"Laki-laki 25 tahun ke IGD dengan kedua telinga nyeri dan berdenging sejak 1 hari setelah menyelam (diving) di laut. Tanda vital normal. Membran timpani tampak merah kebiruan dengan gelembung udara. Apakah diagnosis yang tepat?","opts":["Otitis media kronik","Otitis media akut","Miringitis bulosa","Trauma akustik","Barotrauma"],"ans":4,"why":"Perubahan tekanan saat menyelam/penerbangan dengan tuba Eustachius tidak membuka → barotrauma telinga tengah: nyeri, tinitus, MT retraksi/hemoragik (merah kebiruan), efusi/gelembung udara di telinga tengah. Terapi: dekongestan, analgetik; cegah dengan Valsalva.","ref":[28],"tags":["Barotrauma"],"skdi":"4A","src":"kunci","cards":[{"q":"Barotrauma telinga: penyebab?","a":"Perubahan tekanan (menyelam, pesawat) + tuba tidak membuka"}],"xp":[112,113]},
{"id":"tht-x09","lat":"fk-matatht","ln":109,"lp":115,"stem":"Perempuan 18 tahun dengan telinga kanan sangat gatal sejak 2 hari; hobi berenang dan sering membersihkan telinga. Pendengaran kanan sedikit menurun; tanpa nyeri, cairan, atau demam. Otoskopi: kotoran seperti kapas berwarna hitam. Apakah tatalaksana yang tepat?","opts":["Mikonazol","Nistatin 100.000 IU/g","Ear toilet dengan asam asetat 2%","Salep antibiotik polimiksin","Tampon antibiotik"],"ans":0,"why":"Gatal hebat, debris seperti kapas/tisu basah berwarna hitam (Aspergillus niger; putih = Candida) di liang telinga, faktor lembap (berenang) → otomikosis. Terapi: bersihkan liang telinga + antijamur topikal (mikonazol/klotrimazol).","ref":[16,18],"tags":["Otomikosis"],"skdi":"4A","src":"kunci","cards":[{"q":"Otomikosis: debris hitam?","a":"Aspergillus niger"},{"q":"Otomikosis: debris putih?","a":"Candida albicans"},{"q":"Terapi otomikosis?","a":"Ear toilet + antijamur topikal (mikonazol)"}],"xp":[116,117]},
{"id":"tht-x10","lat":"fk-matatht","ln":110,"lp":118,"stem":"Perempuan 34 tahun dengan pusing berputar disertai mual dan muntah yang muncul saat bepergian jauh dengan mobil (Jakarta–Lampung). Telinga berdenging dan penurunan pendengaran disangkal. Otoskopi normal. Apakah diagnosis dan terapi farmakologis yang tepat?","opts":["Labirinitis dan dimenhidrinat","Motion sickness dan dimenhidrinat","BPPV dan betahistin mesilat","Ménière dan furosemid","Motion sickness dan setirizin"],"ans":1,"why":"Vertigo, mual-muntah yang dipicu perjalanan → motion sickness (konflik vestibular-visual). Terapi: antihistamin sedatif/antiemetik (dimenhidrinat) atau skopolamin, idealnya sebelum perjalanan. Setirizin non-sedatif kurang efektif.","ref":[37,38,41],"tags":["Motion sickness"],"skdi":"4A","src":"kunci","cards":[{"q":"Obat motion sickness?","a":"Dimenhidrinat / skopolamin"}],"xp":[119,120]},
{"id":"tht-x11","lat":"fk-matatht","ln":111,"lp":121,"stem":"Anak laki-laki 7 tahun dengan nyeri telinga kiri sejak 1 hari dan merasa ada sesuatu yang bergerak-gerak di telinga kiri. Riwayat mengorek telinga dan trauma disangkal. Otoskopi telinga kiri seperti gambar (serangga hidup di liang telinga). Apakah tindakan awal yang tepat?","opts":["Tampon basah yang ditetesi rivanol","Ekstraksi dengan forseps aligator","Ekstraksi dengan hook","Irigasi dengan air hangat sesuai suhu tubuh","Tetes karbogliserin 10% selama 3 hari"],"ans":0,"why":"Serangga HIDUP di liang telinga → matikan dulu (kunci: tampon basah dengan rivanol; alternatif minyak/lidokain/alkohol) agar tidak bergerak dan melukai membran timpani, baru diekstraksi.","ref":[16,17],"tags":["Benda asing telinga"],"skdi":"4A","src":"kunci","cards":[],"img":true,"xp":[122,123]},
{"id":"tht-x12","lat":"fk-matatht","ln":112,"lp":124,"stem":"Perempuan 16 tahun dengan hidung gatal dan bersin-bersin sejak 1 tahun, hilang timbul setiap 2 hari (kurang dari 4 hari per minggu); keluar cairan encer terus-menerus sampai mengganggu konsentrasi belajar. Riwayat dermatitis atopik. Rinoskopi: kavum nasi sempit, konka edema, sekret serosa. Apakah diagnosis dan tatalaksana yang tepat?","opts":["Rinitis alergi intermiten ringan; antivirus","Rinitis alergi intermiten sedang-berat; antihistamin","Rinitis alergi intermiten ringan; dekongestan","Rinitis alergi persisten ringan; antihistamin","Rinitis alergi persisten sedang-berat; steroid nasal"],"ans":1,"why":"ARIA: intermiten = gejala < 4 hari/minggu ATAU < 4 minggu; persisten = ≥ 4 hari/minggu DAN ≥ 4 minggu. Sedang-berat bila mengganggu tidur, sekolah/kerja, aktivitas. Gejala tiap 2 hari + mengganggu belajar → intermiten sedang-berat; kunci: antihistamin (± kortikosteroid intranasal).","ref":[45,46,48],"tags":["Rinitis alergi"],"skdi":"4A","src":"kunci","cards":[{"q":"ARIA intermiten?","a":"< 4 hari/minggu atau < 4 minggu"},{"q":"ARIA persisten?","a":"≥ 4 hari/minggu dan ≥ 4 minggu"},{"q":"ARIA sedang-berat?","a":"Mengganggu tidur/sekolah/kerja/aktivitas"}],"xp":[125,126]},
{"id":"tht-x13","lat":"fk-matatht","ln":113,"lp":128,"stem":"Laki-laki 25 tahun dengan nyeri menelan sejak 3 hari, disertai batuk, demam, dan tenggorokan terasa bengkak. Suhu 38 °C. Tonsil hiperemis T2/T2 dengan detritus keabuan, faring hiperemis. Leukosit 16.000/mm³. Apakah tatalaksana yang tepat?","opts":["Siprofloksasin dan parasetamol","Penisilin dan parasetamol","Dekstrometorfan dan parasetamol","Obat kumur dan parasetamol","Vitamin C dan parasetamol"],"ans":1,"why":"Tonsilofaringitis akut dengan detritus, demam, leukositosis → bakterial (GABHS). Antibiotik pilihan: penisilin (atau amoksisilin) 10 hari + analgetik-antipiretik.","ref":[67,68,70],"tags":["Tonsilofaringitis bakterial"],"skdi":"4A","src":"kunci","cards":[],"xp":[129,130]},
{"id":"tht-x14","lat":"fk-matatht","ln":114,"lp":131,"stem":"Perempuan 40 tahun ke IGD dengan sesak napas sejak 2 jam, diawali nyeri tenggorok dan leher; riwayat gigi berlubang sejak 6 tahun. Pembengkakan ekstraoral rahang bawah bilateral simetris, keras, lidah terangkat. SpO₂ 86%, dengan O₂ nasal kanul 2 lpm SpO₂ 84%. Apakah diagnosis dan tatalaksana yang tepat?","opts":["Angina Ludwig; NRM 15 lpm","Angina Ludwig; intubasi","Angina Ludwig; trakeostomi","Abses submandibula; intubasi","Abses submandibula; trakeostomi"],"ans":2,"why":"Selulitis submandibula-sublingual bilateral keras dengan lidah terdorong ke atas, sumber gigi → angina Ludwig dengan obstruksi jalan napas. Intubasi orotrakeal sangat sulit/berisiko (lidah terangkat, edema) → jalan napas definitif dengan trakeostomi (sering dengan anestesi lokal) + antibiotik IV.","ref":[82,83,85],"tags":["Angina Ludwig"],"skdi":"3A","src":"kunci","cards":[{"q":"Angina Ludwig dengan obstruksi napas: airway?","a":"Trakeostomi (intubasi sulit)"}],"xp":[132,133]},
{"id":"tht-x15","lat":"fk-matatht","ln":115,"lp":134,"stem":"Anak 7 tahun dengan nyeri menelan sejak 4 hari, suara serak dan demam; riwayat batuk berdahak hilang timbul 6 bulan. Suhu 38 °C. Trismus (+), halitosis (+), tonsil T3/T2, fluktuasi (+), kripta melebar (+), uvula terdeviasi ke kanan. Apakah diagnosis dan tatalaksana yang tepat?","opts":["Abses peritonsil (quinsy); insisi dan drainase","Abses peritonsil (quinsy); penisilin G 500 mg/6 jam","Abses retrofaring; insisi dan drainase","Angina Ludwig; amankan jalan napas","Abses retrofaring; amoksiklav 2×625 mg"],"ans":0,"why":"Trismus, hot potato voice, pembengkakan peritonsil berfluktuasi, uvula terdorong ke sisi sehat → abses peritonsil (quinsy). Terapi: aspirasi/insisi-drainase + antibiotik; tonsilektomi elektif kemudian.","ref":[84],"tags":["Abses peritonsil"],"skdi":"3A","src":"kunci","cards":[],"xp":[135,136]},
{"id":"tht-x16","lat":"fk-matatht","ln":116,"lp":137,"stem":"Wanita 20 tahun dengan bengkak di sisi kiri leher sejak 4 hari, nyeri dan demam tinggi. Riwayat penurunan pendengaran kiri dan keluar cairan telinga lama yang tidak diobati. Pemeriksaan seperti gambar: bengkak di leher di bawah mastoid, fluktuasi (+), nyeri tekan (+). Apakah diagnosis yang tepat?","opts":["Mastoiditis","Abses Bezold","Abses Luc","Labirinitis","Abses subperiosteal"],"ans":1,"why":"Komplikasi OMSK/mastoiditis: pus menembus ujung mastoid ke medial dan turun di bawah m. sternokleidomastoideus → abses Bezold (bengkak leher). Subperiosteal: retroaurikular; Luc: di atas/depan telinga (temporal).","ref":[25,26],"tags":["Abses Bezold","OMSK"],"skdi":"3A","src":"kunci","cards":[],"img":true,"xp":[138,139]}
]});
